import test from 'node:test';
import assert from 'node:assert/strict';
import { bounded } from './bounded.js';

const cases = [
  ['negative interval: below lower bound', -12, -10, -2, -10],
  ['negative interval: at lower bound', -10, -10, -2, -10],
  ['negative interval: inside bounds', -6, -10, -2, -6],
  ['negative interval: at upper bound', -2, -10, -2, -2],
  ['negative interval: above upper bound', -1, -10, -2, -2],
  ['zero-crossing interval: below lower bound', -7, -5, 4, -5],
  ['zero-crossing interval: at lower bound', -5, -5, 4, -5],
  ['zero-crossing interval: negative interior value', -2, -5, 4, -2],
  ['zero-crossing interval: zero interior value', 0, -5, 4, 0],
  ['zero-crossing interval: positive interior value', 2, -5, 4, 2],
  ['zero-crossing interval: at upper bound', 4, -5, 4, 4],
  ['zero-crossing interval: above upper bound', 7, -5, 4, 4],
  ['zero lower bound: below bounds', -1, 0, 5, 0],
  ['zero lower bound: at lower bound', 0, 0, 5, 0],
  ['zero lower bound: inside bounds', 2, 0, 5, 2],
  ['zero lower bound: at upper bound', 5, 0, 5, 5],
  ['zero lower bound: above bounds', 6, 0, 5, 5],
  ['zero upper bound: below bounds', -6, -5, 0, -5],
  ['zero upper bound: at lower bound', -5, -5, 0, -5],
  ['zero upper bound: inside bounds', -2, -5, 0, -2],
  ['zero upper bound: at upper bound', 0, -5, 0, 0],
  ['zero upper bound: above bounds', 1, -5, 0, 0],
  ['equal negative bounds: value below', -4, -3, -3, -3],
  ['equal negative bounds: value equal', -3, -3, -3, -3],
  ['equal negative bounds: value above', -2, -3, -3, -3],
  ['equal zero bounds: value below', -1, 0, 0, 0],
  ['equal zero bounds: value equal', 0, 0, 0, 0],
  ['equal zero bounds: value above', 1, 0, 0, 0],
];

for (const [name, value, lower, upper, expected] of cases) {
  test(name, () => {
    assert.strictEqual(bounded(value, lower, upper), expected);
  });
}

const reversedCases = [
  ['reversed bounds: value below both bounds', -5],
  ['reversed bounds: value at smaller bound', -4],
  ['reversed bounds: value between bounds', 0],
  ['reversed bounds: value at larger bound', 3],
  ['reversed bounds: value above both bounds', 4],
];

for (const [name, value] of reversedCases) {
  test(name, () => {
    assert.throws(() => bounded(value, 3, -4), RangeError);
  });
}
